def infer_slice(node, context: InferenceContext | None = None):
    """Understand `slice` calls."""
    call = arguments.CallSite.from_call(node, context=context)
    if call.keyword_arguments:
        raise UseInferenceDefault("TypeError: slice() does not accept keyword arguments")

    # slice() can take 1-3 positional arguments: slice(stop), slice(start, stop), slice(start, stop, step)
    if len(call.positional_arguments) > 3:
        raise UseInferenceDefault(
            f"TypeError: slice expected at most 3 arguments, got {len(call.positional_arguments)}"
        )

    # Get the arguments and infer them
    args = []
    for arg in call.positional_arguments:
        try:
            inferred = next(arg.infer(context=context))
            if isinstance(inferred, util.UninferableBase):
                args.append(None)
            elif isinstance(inferred, nodes.Const) and isinstance(inferred.value, (int, type(None))):
                args.append(inferred.value)
            else:
                # If the argument is not an integer or None, use None as default
                args.append(None)
        except (InferenceError, StopIteration):
            args.append(None)

    # Fill in missing arguments with None
    while len(args) < 3:
        args.append(None)

    # Create a slice object
    start, stop, step = args
    slice_obj = objects.Slice(
        start=start,
        stop=stop,
        step=step,
        lineno=node.lineno,
        col_offset=node.col_offset,
        parent=node.parent,
    )
    return slice_obj

